from fastapi import FastAPI, Depends, HTTPException
from fastapi.security import HTTPBearer, HTTPDigest, OpenIdConnect
from fastapi.testclient import TestClient
import pytest

app = FastAPI()

bearer_scheme = HTTPBearer()
digest_scheme = HTTPDigest()
oidc_scheme = OpenIdConnect(openIdConnectUrl="https://example.com/.well-known/openid-configuration")

@app.get("/bearer")
async def read_bearer(token=Depends(bearer_scheme)):
    return {"token": token}

@app.get("/digest")
async def read_digest(token=Depends(digest_scheme)):
    return {"token": token}

@app.get("/oidc")
async def read_oidc(token=Depends(oidc_scheme)):
    return {"token": token}

client = TestClient(app)

def test_bearer_not_authenticated():
    response = client.get("/bearer")
    assert response.status_code == 401
    assert response.headers["WWW-Authenticate"] == "Bearer"

def test_digest_not_authenticated():
    response = client.get("/digest")
    assert response.status_code == 401
    assert response.headers["WWW-Authenticate"] == "Digest"

def test_oidc_not_authenticated():
    response = client.get("/oidc")
    assert response.status_code == 401
    assert response.headers["WWW-Authenticate"] == "OpenIdConnect"

def test_bearer_custom_status():
    app_custom = FastAPI()
    bearer_custom = HTTPBearer(not_authenticated_status_code=403)
    @app_custom.get("/bearer")
    async def read_bearer(token=Depends(bearer_custom)):
        return {"token": token}

    client_custom = TestClient(app_custom)
    response = client_custom.get("/bearer")
    assert response.status_code == 403
    assert "WWW-Authenticate" not in response.headers

def test_bearer_invalid_scheme():
    response = client.get("/bearer", headers={"Authorization": "Basic abc"})
    assert response.status_code == 403 # This should still be 403 as per implementation

def test_digest_invalid_scheme():
    response = client.get("/digest", headers={"Authorization": "Basic abc"})
    assert response.status_code == 403 # This should still be 403 as per implementation

if __name__ == "__main__":
    import pytest
    pytest.main([__file__])

